#include <xcb/xcb.h>
#include <stdio.h>
#include <stdlib.h>
static void check(xcb_connection_t*c,xcb_void_cookie_t k){xcb_generic_error_t*e=xcb_request_check(c,k);if(e){fprintf(stderr,"unexpected X error %u request %u\n",e->error_code,e->major_code);free(e);exit(2);}}
static xcb_window_t make(xcb_connection_t*c,xcb_window_t parent){xcb_window_t w=xcb_generate_id(c);check(c,xcb_create_window_checked(c,XCB_COPY_FROM_PARENT,w,parent,0,0,16,16,0,XCB_WINDOW_CLASS_INPUT_OUTPUT,XCB_COPY_FROM_PARENT,0,NULL));return w;}
int main(void){int screen; xcb_connection_t*a=xcb_connect(NULL,&screen),*b=xcb_connect(NULL,NULL);if(xcb_connection_has_error(a)||xcb_connection_has_error(b))return 2;xcb_screen_iterator_t it=xcb_setup_roots_iterator(xcb_get_setup(a));while(screen--)xcb_screen_next(&it);xcb_window_t root=it.data->root;
for(int fixed=0;fixed<2;fixed++){int failures=0;for(int i=0;i<100;i++){xcb_window_t parent=make(a,root),child=make(b,root);check(a,xcb_reparent_window_checked(a,child,parent,0,0));if(fixed)check(a,xcb_reparent_window_checked(a,child,root,0,0));check(a,xcb_destroy_window_checked(a,parent));xcb_generic_error_t*e=xcb_request_check(b,xcb_change_property_checked(b,XCB_PROP_MODE_REPLACE,child,XCB_ATOM_WM_NAME,XCB_ATOM_STRING,8,4,"test"));if(e){if(e->error_code!=XCB_WINDOW||e->major_code!=18)return 3;failures++;free(e);}else check(b,xcb_destroy_window_checked(b,child));}printf("%s: %d/100 BadWindow on ChangeProperty\n",fixed?"detach before parent destruction":"destroy parent before detach",failures);if(failures!=(fixed?0:100))return 4;}xcb_disconnect(b);xcb_disconnect(a);return 0;}
